window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"3xKgJBbzz7E","speaker":"Mukhtar Tileuberdi","role":"Minister for Foreign Affairs","country":"Kazakhstan","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=3xKgJBbzz7E","date":"20260926","title":"🇰🇿 Kazakhstan - Minister for Foreign Affairs Addresses UN General Debate, 81st Session | #UNGA","seconds":1167,"words":2072,"counts":{"claims":35,"promises":7,"attacks":0},"topics":[{"topic":"UN reform","share":0.1119,"seconds":131},{"topic":"Gaza","share":0.1114,"seconds":130},{"topic":"AI governance","share":0.1106,"seconds":129},{"topic":"Nuclear disarmament","share":0.1083,"seconds":126},{"topic":"Water security","share":0.0613,"seconds":72},{"topic":"Kazakhstan domestic reform","share":0.0604,"seconds":70},{"topic":"Health systems","share":0.0595,"seconds":69},{"topic":"Central Asia ecology","share":0.0584,"seconds":68},{"topic":"Kazakhstan energy security","share":0.0554,"seconds":65},{"topic":"Humanitarian law","share":0.054,"seconds":63},{"topic":"Kazakhstan elections","share":0.0536,"seconds":63},{"topic":"UNGA 81st session","share":0.0522,"seconds":61},{"topic":"Water governance","share":0.052,"seconds":61},{"topic":"UN cooperation","share":0.0508,"seconds":59}],"timeline":[[1,62,"UNGA 81st session"],[64,134,"Kazakhstan domestic reform"],[136,198,"Kazakhstan elections"],[199,266,"UN reform"],[268,332,"UN reform"],[332,396,"Nuclear disarmament"],[398,460,"Nuclear disarmament"],[462,527,"Kazakhstan energy security"],[528,594,"Gaza"],[596,660,"Gaza"],[661,724,"Humanitarian law"],[725,794,"Health systems"],[796,864,"Central Asia ecology"],[866,937,"Water security"],[939,999,"Water governance"],[1000,1066,"AI governance"],[1067,1131,"AI governance"],[1132,1191,"UN cooperation"]],"stances":{"UNGA 81st session":"Mukhtar Tileuberdi congratulates the newly elected president of the 81st session and assures him of Kazakhstan's full support.","Kazakhstan domestic reform":"Mukhtar Tileuberdi states that Kazakhstan has undertaken profound political transformation and adopted a new constitution to reinforce sustainable development, emphasizing human dignity, education, and the rule of law.","Kazakhstan elections":"Mukhtar Tileuberdi notes the recent election results in Kazakhstan and expresses concern over global uncertainty, division, and the erosion of trust among nations.","UN reform":"Mukhtar Tileuberdi supports UN reform and emphasizes that its success should be measured by conflict prevention and crisis response rather than cuts, while calling for Security Council reform to include broader representation from Asia, Africa, Latin America, developing countries, and middle powers.","Nuclear disarmament":"Mukhtar Tileuberdi argues that Kazakhstan's experience with nuclear disarmament strengthened its sovereignty and security, while warning that current international trust is endangered by the expiration of New START and the lack of progress at the NPT review conference.","Kazakhstan energy security":"Mukhtar Tileuberdi strongly condemns drone attacks on Kazakh oil infrastructure and calls for adherence to international law to protect critical assets.","Gaza":"Mukhtar Tileuberdi supports a two-state solution and calls for the implementation of plans to end the Gaza conflict, including humanitarian assistance and civilian reconstruction.","Humanitarian law":"Mukhtar Tileuberdi expresses concern over the erosion of civilian protection and states that Kazakhstan is advancing a global initiative to strengthen political commitment to international humanitarian law.","Health systems":"Mukhtar Tileuberdi reaffirms commitment to advancing primary health care as the cornerstone of universal health coverage and calls for UN member states to join a global coalition on the issue.","Central Asia ecology":"Mukhtar Tileuberdi states that the regional ecological summit and related declarations provide a foundation for advancing environmental cooperation in Central Asia.","Water security":"Mukhtar Tileuberdi states that water security is fundamental to well-being, resilience, public health, food and energy security, climate resilience, and peace.","Water governance":"Mukhtar Tileuberdi states that global water governance is fragmented and supports President Tokay's proposal to establish an international water organization under UN auspices to improve coherence and accountability.","AI governance":"Mukhtar Tileuberdi states that Kazakhstan is investing in AI infrastructure and has adopted new laws, but emphasizes the need for urgent international cooperation to ensure AI remains human-centered and safe.","UN cooperation":"Mukhtar Tileuberdi states that multilateralism must deliver tangible benefits and that member states must honor commitments, while affirming Kazakhstan's role as a reliable partner for peace and security."},"claims":[{"t":33,"quote":"I congratulate his excellency, Mr. Halur Rahman on his election as the president of the 81st session of the general assembly","topic":"UNGA 81st session","kind":"fact"},{"t":98,"quote":"Kazakhstan has embarked on profound political transformation in response to societal demand and emerging challenges.","topic":"Kazakhstan domestic reform","kind":"fact"},{"t":109,"quote":"Our new constitution reinforces the foundations of national sustainable development by placing greater emphasis on human dignity, human capital, education, innovation and environmental","topic":"Kazakhstan domestic reform","kind":"fact"},{"t":136,"quote":"Elections last month to the new coralai brought into unicameal parliament and diverse set of voices including historic high 34% of women.","topic":"Kazakhstan elections","kind":"number"},{"t":204,"quote":"President Okayaf has repeatedly underscored the indispensable role of the United Nations as a single universal platform uniquely capable of bringing the states together to address the challenges we face.","topic":"UN reform","kind":"fact"},{"t":255,"quote":"Broader representation of Asia, Africa and Latin America in the council as well as greater voice for developing countries and for middle powers is a moral imperative.","topic":"UN reform","kind":"fact"},{"t":302,"quote":"World military expenditures reached a record $2.9 trillion dollar in 2025.","topic":"UN reform","kind":"number"},{"t":311,"quote":"Our small planet is home to more than 12,000 nuclear weapons, each one capable of untold damage and sorrow.","topic":"UN reform","kind":"number"},{"t":338,"quote":"This year marks 35 years since the closure of the Cip Palatin nuclear test site, 30 years since the CTBT opened for signature and 20 years since the signing of the C Palatin treaty on nuclear weapon free zone in Central Asia.","topic":"Nuclear disarmament","kind":"number"},{"t":357,"quote":"Our experience uh of reannouncing the world fourth largest nuclear arsenal did not weaken our state.","topic":"Nuclear disarmament","kind":"fact"},{"t":398,"quote":"They remain responsible until we secure world free of nuclear weapons.","topic":"Nuclear disarmament","kind":"fact"},{"t":404,"quote":"Kazakhstan advocates the relaunch of high level dialogue among nuclear powers and is ready to host one of their next meetings.","topic":"Nuclear disarmament","kind":"fact"},{"t":464,"quote":"Kazakhstan strongly condemns the repeated drone attacks against Kazak crude oil export infrastructure, including against commercial vessels in the Black Sea basin.","topic":"Kazakhstan energy security","kind":"fact"},{"t":477,"quote":"Such incidents endangered civilian navigation, disrupt international trade and threatened the stability of global energy supplies.","topic":"Kazakhstan energy security","kind":"fact"},{"t":528,"quote":"A just as lasting peace in the Middle East requires an independent, sovereign, and viable state of Palestine living side by side with Israel in peace and security.","topic":"Gaza","kind":"fact"},{"t":541,"quote":"We support the new the New York declaration as a framework of for tangible, time bound and irreversible steps toward this two-state solution.","topic":"Gaza","kind":"fact"},{"t":567,"quote":"Kazan's calls for the full and goodfaith implementation of the comprehensive plan to end the Gaza conflict and security council resolution 2803.","topic":"Gaza","kind":"fact"},{"t":596,"quote":"Kazan's peacekeepers in Yundov and UNIFIL reflect our readiness to assume practical responsibility and contribute to the international mandated stabilization forces in Gaza.","topic":"Gaza","kind":"fact"},{"t":612,"quote":"Kazan formally announced its intention to join the Abraham eccorts.","topic":"Gaza","kind":"fact"},{"t":661,"quote":"we have watched with growing concern in the recent years the erosion of pro protection of civilians in conflict zones","topic":"Humanitarian law","kind":"fact"},{"t":678,"quote":"Kazakhstan is advancing the global initiative to galvanize political commitment to international humanitarian law","topic":"Humanitarian law","kind":"fact"},{"t":697,"quote":"Kazakhstan is working with the United Nations to operationalize the United Nations regional center for the sustainable development goals for Central Asia and Afghanistan in Almati City","topic":"Humanitarian law","kind":"fact"},{"t":742,"quote":"2026 has been designated by this body as the international year of voluntary volunteers for sustainable development.","topic":"Health systems","kind":"fact"},{"t":753,"quote":"This initiative originally at President Stokay's suggestion has given new impetus to volunteerism as a force for stronger communities youth engagement and environmental action in Kazakhstan and elsewhere.","topic":"Health systems","kind":"self_credit"},{"t":796,"quote":"The regional ecological summit held in Dana in April reaffirming that climate, water, food and health challenges cannot be addressed in isolation.","topic":"Central Asia ecology","kind":"fact"},{"t":821,"quote":"On the same day, the heads of states of the founding countries of the international fund for saving the RLC declared an international day of RLC and Amudara and Saria rivers with the aim of raising global awareness of the region's environmental challenges and mobilizing greater international support for their","topic":"Central Asia ecology","kind":"fact"},{"t":919,"quote":"Healthy ecosystem depend on water. Water security is fundamental to the well-being and the resilience of our","topic":"Water security","kind":"fact"},{"t":931,"quote":"Water underpins public health, food and energy security, climate resilience and peace.","topic":"Water security","kind":"fact"},{"t":945,"quote":"The recent devastating floods in the mountains regions of Nepal and China remind us of the growing risk associated with water and climate related disasters.","topic":"Water governance","kind":"fact"},{"t":958,"quote":"President Tokay has proposed the establishment of international water organization under the oices of the United Nations.","topic":"Water governance","kind":"fact"},{"t":1019,"quote":"At home, we are investing uh computing capacity, digital infrastructure and AI skills.","topic":"AI governance","kind":"fact"},{"t":1032,"quote":"And we have recently adopted law on artificial intelligence and new digital code.","topic":"AI governance","kind":"fact"},{"t":1072,"quote":"the use of AI in warfare and cyber operations could have farreaching consequences for international stability","topic":"AI governance","kind":"fact"},{"t":1081,"quote":"Kazakhstan supports stronger international rules and cooperation, including through the United Nations global mechanism on ICT security and UN global dialogue on AI governance","topic":"AI governance","kind":"fact"},{"t":1132,"quote":"The system of international cooperation we call in whose famous hall we stand today depends on us just as we depend on it through the institution of m multiritalism must deliver tangible benefits but equally true we the member states must honor our commitments adhere to global standards and work Together","topic":"UN cooperation","kind":"fact"}],"promises":[{"t":43,"quote":"assure him that he can count on Kazan full support throughout this session","topic":"UNGA 81st session","kind":"promise"},{"t":52,"quote":"Kazastan remains fully committed to the pupils and principles of the charter of the United Nations and to effective multilateral cooperation","topic":"UNGA 81st session","kind":"promise"},{"t":414,"quote":"We will also continue advancing our earlier proposal to strengthen the BWC through establishing an international agency for biological","topic":"Nuclear disarmament","kind":"promise"},{"t":554,"quote":"My country stands ready to support every effort aimed at the maintaining unhindered humanitarian assistance, protection of civilians and recovery of Gaza.","topic":"Gaza","kind":"promise"},{"t":583,"quote":"President Okive has committed the contribute to the stabilization of Gaza by supporting civilian reconstruction, ensuring food security and providing digital government solution.","topic":"Gaza","kind":"promise"},{"t":990,"quote":"We will continue to advance this discussion in the leadup for the 2026 United Nations Water Conference in Abu Dhabi.","topic":"Water governance","kind":"promise"},{"t":1163,"quote":"Kazakhstan will remain reliable partner for peace, security, and sustainable development. We will continue to choose cooperation over coordination and work with all member states to strengthen the United Nations and turn our shared commitments into meaningful action","topic":"UN cooperation","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"UNGA 81st session","text":"And now I give the floor to his excellency Mktar Tilo Berdi, Minister for Foreign Affairs of Kazakhstan. Mr. President, distinguished delegates, I congratulate his excellency, Mr. Halur Rahman on his election as the president of the 81st session of the general assembly and assure him that he can count on Kazan full support throughout this session. Excellencies, Kazastan remains fully committed to the pupils and principles of the charter of the United Nations and to effective multilateral cooperation."},{"t":64,"topic":"Kazakhstan domestic reform","text":"Guided by pragmatic and proactive foreign policy, we continue our efforts to strengthen international peace and security and to advance pragmatic solutions to our shared global For Kazakhstan, multilateralism is a key instrument for building trust, finding common ground, and delivering results for our citizens and future generations. It's a key component of our own long-term social economic development. Kazakhstan has embarked on profound political transformation in response to societal demand and emerging challenges. Our new constitution reinforces the foundations of national sustainable development by placing greater emphasis on human dignity, human capital, education, innovation and environmental I have also continued to strengthen the rule of law, public accountability and protection of human rights."},{"t":136,"topic":"Kazakhstan elections","text":"Elections last month to the new coralai brought into unicameal parliament and diverse set of voices including historic high 34% of women. Mr. President, we express our country's grave concern as the world continues its slight toward uncertainty and division. The erosion of trust among nations is rapidly reshaping the international order. Our collective inability to prevent conflicts, our collective indifference toward humanitarian crisis and our collective reluctance to seek common solutions to shared challenges are all becoming normalized. Trust cannot be restored when international law is applied. selectively and commitments remain Our response must be grounded in the fundamental values we have affirmed together."},{"t":199,"topic":"UN reform","text":"Freedom, equality, justice, and respect for human dignity. President Okayaf has repeatedly underscored the indispensable role of the United Nations as a single universal platform uniquely capable of bringing the states together to address the challenges we face. But to feel its potential, U must be able to act, adapt and deliver. We fully support the UN at initiative. The success of the reform should be measured not by what is cut or re reorganized, but by whether the United Nations prevents conflicts more effectively, responds more rapidly to crisis, and delivers better results for all member Central to this renewal is reform of the security council. Broader representation of Asia, Africa and Latin America in the council as well as greater voice for developing countries and for middle powers is a moral imperative."},{"t":268,"topic":"UN reform","text":"Equitable geographical representation must apply throughout the United Nations system as a condition of legitimacy and The selection of the next secretary general will be one of the defining moment of this session and Kazakhstan supports a transparent, inclusive and merit-basing process conducted in full accordance with the chapter. Mr. President, the international security environment continues to World military expenditures reached a record $2.9 trillion dollar in 2025. Our small planet is home to more than 12,000 nuclear weapons, each one capable of untold damage and sorrow. Every year we seem to lose more biodiversity yet gain more armaments. For Kazakhstan, nuclear disarmament in particular is not an abstract doctrine."},{"t":332,"topic":"Nuclear disarmament","text":"It's a responsibility born on national This year marks 35 years since the closure of the Cip Palatin nuclear test site, 30 years since the CTBT opened for signature and 20 years since the signing of the C Palatin treaty on nuclear weapon free zone in Central Asia. Our experience uh of reannouncing the world fourth largest nuclear arsenal did not weaken our state. To the contrary through international trust it strengthens sovereignity, enhance security and promotes development. Today the trust is again in danger. New start has expired while the 2026 NPT review conference ended without substantive outcome for the third consecutive cycle. Nuclear weapon states must never confuse the absence of agreement with vacuum of obligation."},{"t":398,"topic":"Nuclear disarmament","text":"They remain responsible until we secure world free of nuclear weapons. Kazakhstan advocates the relaunch of high level dialogue among nuclear powers and is ready to host one of their next meetings. We will also continue advancing our earlier proposal to strengthen the BWC through establishing an international agency for biological Distinguished delegates, peace and stability are prerequisite for sustainable development. We stand firmly for diplomacy and dialogue and against the escalation of tension and the use of force. We remain deeply concerned about Ukrainian crisis which continues to take lives, erode global trust and undermine international security. Even the most difficult conflicts must ultimately be resolved through diplomacy and negotiation."},{"t":462,"topic":"Kazakhstan energy security","text":"Beyond the tragic loss of life, Kazakhstan strongly condemns the repeated drone attacks against Kazak crude oil export infrastructure, including against commercial vessels in the Black Sea basin. Such incidents endangered civilian navigation, disrupt international trade and threatened the stability of global energy supplies. We call on We call on all parties to uphold international law and take all necessary measures to protect critical infrastructure and ensure the safety and continuity of civilian commerce. Political and diplomatic means remain the only viable path towards ending hostilities and achieving sustainable resolution of the Middle East crisis. The ongoing escalation carries serious implications for regional and international peace and security as well as for economic stability, transport connectivity and energy security."},{"t":528,"topic":"Gaza","text":"A just as lasting peace in the Middle East requires an independent, sovereign, and viable state of Palestine living side by side with Israel in peace and security. We support the new the New York declaration as a framework of for tangible, time bound and irreversible steps toward this two-state solution. My country stands ready to support every effort aimed at the maintaining unhindered humanitarian assistance, protection of civilians and recovery of Gaza. Kazan's calls for the full and goodfaith implementation of the comprehensive plan to end the Gaza conflict and security council resolution 2803. As a member of the board of peace, President Okive has committed the contribute to the stabilization of Gaza by supporting civilian reconstruction, ensuring food security and providing digital government solution."},{"t":596,"topic":"Gaza","text":"Kazan's peacekeepers in Yundov and UNIFIL reflect our readiness to assume practical responsibility and contribute to the international mandated stabilization forces in Gaza. Kazan formally announced its intention to join the Abraham eccorts. We see them as an additional platform to infor reinforce the UN brokered political process towards the two-state solution. The long-term stability of Afghanistan remains inseparable from the security and sustainable development of Central Asia. Humanitarian assistance remains indispensable but it cannot be itself break the cycle of poverty, displacement and dependency. Kazakhstan supports pragmatic, coordinated and step-by-step international engagement with Afghanistan with the UN playing the central role."},{"t":661,"topic":"Humanitarian law","text":"Finally, we have watched with growing concern in the recent years the erosion of pro protection of civilians in conflict zones in response together with Brazil, China, France, Jordan, South Africa and the ICRC. Kazakhstan is advancing the global initiative to galvanize political commitment to international humanitarian law. Mr. President, the growing role of middle powers in global affairs is opening new avenues for practical cooperation to achieve SDGs. Kazakhstan is working with the United Nations to operationalize the United Nations regional center for the sustainable development goals for Central Asia and Afghanistan in Almati City. Its success should be measured by what it delivers. I thank my colleagues, the foreign ministers of Central Asia, for helping shape a practical and focused agenda for the center."},{"t":725,"topic":"Health systems","text":"Reaffirming our commitment advancing primary health care as the cornerstone of universal health coverage, we call upon UN member states to join the global coalition on primary health care. 2026 has been designated by this body as the international year of voluntary volunteers for sustainable development. This initiative originally at President Stokay's suggestion has given new impetus to volunteerism as a force for stronger communities youth engagement and environmental action in Kazakhstan and elsewhere. Hundreds or thousands of people have joined volunteer activities. Excellencies, environmental challenges are among the defining issues of our time. Climate change, biodiversity loss, land degradation and the growing frequency of natural disaster are placing increasing pressure on our societies and economies."},{"t":796,"topic":"Central Asia ecology","text":"The regional ecological summit held in Dana in April reaffirming that climate, water, food and health challenges cannot be addressed in isolation. Its declaration environmental solidarity of Central Asia provides a strong foundation for advancing regional cooperation on environmental protection and sustainable development. On the same day, the heads of states of the founding countries of the international fund for saving the RLC declared an international day of RLC and Amudara and Saria rivers with the aim of raising global awareness of the region's environmental challenges and mobilizing greater international support for their We are grateful for the support of UN member states and partners for President Okive's proposal to proclaim 22nd April as the international day of greening of the planet aimed at amplifying global efforts to restore ecosystem."},{"t":866,"topic":"Water security","text":"Kazakhstan pursues a human centered approach to contemporary challenges emphasizing peaceuilding, dialogue and cooperation as an essential response to the complex global challenges of our time. This approach is underpinned by broader mental shift toward environmental stewardship, civic engagement and care for the public good. It's reflected in nationwide efforts to improve public spaces, advance largecale greening, and promote the values of respect for the rule of law, active and responsible patriotism, volunteerism and compassion as integral element of everyday life and civic culture. This bring us to another critical topic of our days. Healthy ecosystem depend on water. Water security is fundamental to the well-being and the resilience of our Water underpins public health, food and energy security, climate resilience and peace."},{"t":939,"topic":"Water governance","text":"Yet, despite its fundamental importance, global water governance remains fragmented. The recent devastating floods in the mountains regions of Nepal and China remind us of the growing risk associated with water and climate related disasters. In this context, President Tokay has proposed the establishment of international water organization under the oices of the United Nations. The pupils is to make international water governance more coherent, accountable and capable of effective implementation. Kazakhstan's calls for inclusive member state-led process to explore options for strengthening the institutional architecture for water within the United We will continue to advance this discussion in the leadup for the 2026 United Nations Water Conference in Abu Dhabi."},{"t":1000,"topic":"AI governance","text":"Kazapstan stands ready to work with the all member states and partners to advance this common agenda. Distinguished delegates, artificial intelligence and rapid technological change present another area where urgent international cooperation is needed. At home, we are investing uh computing capacity, digital infrastructure and AI skills. We are forging new trusted partnership on AI governance and emerging technologies. And we have recently adopted law on artificial intelligence and new digital code. But without effective governance at all levels, it will also deepen inequality, create new security risk. as we have seen very recently and widen the digital We also should not let ethical norms fall behind this rapid evolution. AI must remain human centered, safe and subject to meaningful human oversight."},{"t":1067,"topic":"AI governance","text":"These risks are particularly serious in the military domain where the use of AI in warfare and cyber operations could have farreaching consequences for international stability. Kazakhstan supports stronger international rules and cooperation, including through the United Nations global mechanism on ICT security and UN global dialogue on AI governance. At the regional level, we invite partners to engage with the UNESCOP Asia-Pacific Digital Solution Center in Almati City as a platform for sharing expertise and advancing regional digital cooperation. Ladies and gentlemen, one thing is clear. There is a global trust deficit. Restoring trust will take time. But greater trust will not just appear like magic. It's a result of increasing not decreasing international cooperation and we must build it."},{"t":1132,"topic":"UN cooperation","text":"The system of international cooperation we call in whose famous hall we stand today depends on us just as we depend on it through the institution of m multiritalism must deliver tangible benefits but equally true we the member states must honor our commitments adhere to global standards and work Together, Kazakhstan will remain reliable partner for peace, security, and sustainable development. We will continue to choose cooperation over coordination and work with all member states to strengthen the United Nations and turn our shared commitments into meaningful action. And I thank you. &gt;&gt; I thank you. I thank the Minister for Foreign Affairs of Kazakhstan."}],"compare":[{"topic":"UN & its reform","share":0.2149,"mean":0.2047,"rank":83,"others":170},{"topic":"Water Access","share":0.1134,"mean":0.0029,"rank":3,"others":7},{"topic":"Israel–Palestine","share":0.1114,"mean":0.0521,"rank":30,"others":76},{"topic":"Artificial Intelligence","share":0.1106,"mean":0.0502,"rank":31,"others":83},{"topic":"Nuclear Disarmament","share":0.1083,"mean":0.0035,"rank":2,"others":9},{"topic":"Global Health","share":0.0595,"mean":0.0022,"rank":4,"others":6},{"topic":"Central Asia","share":0.0584,"mean":0.0022,"rank":5,"others":5},{"topic":"Kazakhstan","share":0.0554,"mean":0.0,"rank":1,"others":0}]};
